    q(65, "B", "Whose", "「これはだれの帽子ですか。—アカリのものです。」を英語で書こう（2文、Akari's を使う）。", EN("Whose hat is this? It's Akari's.", "Whose hat is this? It is Akari's."), "Whose hat is this? ／ It's Akari's.", near=["Whose hat is this? It's Akari.", "Who's hat is this? It's Akari's."])
    q(65, "B", "Who", "アンケート表を見て答えよう。\n【犬を飼っている：ケン】\nWho keeps a dog? —（2語で）", EN("Ken does."), "Who ＋一般動詞（三単現） ～? には「人＋ does.」。", near=["Ken do.", "Ken is."])
    q(65, "B", "Who", "「ハムスターを飼っているのはだれですか。」を英語で書こう（keeps を使う）。", EN("Who keeps a hamster?", "Who keeps hamsters?"), "Who ＋ keeps ～?", near=["Who keep a hamster?", "Who does keep a hamster?"])
    q(65, "必ず覚えたい語句", "語句", "「私はおなかがいっぱいです。」を英語で書こう（full を使う）。", EN("I'm full.", "I am full."), "full＝満腹で。", near=["I'm hungry.", "I full."])
    q(65, "必ず覚えたい語句", "語句", "「これらの本」を英語2語で書こう。", EN("these books"), "this の複数形 these ＋複数名詞。", near=["this books", "those books"])
