    q(70, "文法③", "疑問詞", "「何曜日」をたずねるときの2語の疑問詞を書こう。", EN("what day"), "what day＝何曜日。", near=["what time", "which day"])
    q(70, "文法③", "疑問詞", "年齢をたずねる「何歳」は、How と何を組み合わせるか。2語で書こう。", EN("how old"), "how old＝何歳。", near=["how many", "how long"])
    q(70, "文法③", "疑問詞", "「どれくらい長く」をたずねる2語の疑問詞を書こう。", EN("how long"), "how long＝どれくらい長く。", near=["how old", "how many"])
    q(70, "文法③", "前置詞", "「月曜日に」と答えるとき、Monday の前に置く前置詞を書こう。", EN("on"), "曜日・日付は on。", near=["in", "at"])
    q(70, "文法③", "前置詞", "「7時に」と答えるとき、seven の前に置く前置詞を書こう。", EN("at"), "時刻は at。", near=["on", "in"])
    q(70, "文法③", "前置詞", "「冬に」と答えるとき、winter の前に置く前置詞を書こう。", EN("in"), "月・季節は in。", near=["on", "at"])
    q(70, "文法③", "前置詞", "「バスで」と答えるとき、bus の前に置く前置詞を書こう。", EN("by"), "交通手段は by（by bus）。", near=["on", "in", "with"])
    q(70, "文法③", "at と in", "「カナダに（住んでいる）」というとき、Canada の前は at と in のどちらか。", EN("in"), "国・町など広い場所は in。", near=["at"])
    q(71, "文法③", "疑問詞", "下線部をたずねる疑問文にしよう。\nThat student is Aya.（下線部：Aya）", EN("Who is that student?", "Who's that student?"), "人をたずねるので Who。", near=["What is that student?"])
    q(71, "文法③", "疑問詞", "下線部をたずねる疑問文にしよう。\nI have ten CDs.（下線部：ten）", EN("How many CDs do you have?"), "数をたずねるので How many ＋複数形。", near=["How many CD do you have?", "How much CDs do you have?"])
    q(71, "文法③", "疑問詞", "下線部をたずねる疑問文にしよう。\nHe is in his room.（下線部：in his room）", EN("Where is he?", "Where's he?"), "場所をたずねるので Where。", near=["Where he is?", "What is he?"])
    q(71, "文法③", "疑問詞", "「あなたのお父さんは何歳ですか。」を英語で書こう。", EN("How old is your father?"), "How old ＋ is ＋主語?", near=["How old your father is?", "How many old is your father?"])
    q(71, "文法③", "疑問詞", "「あなたは何時に起きますか。」を英語で書こう。", EN("What time do you get up?"), "What time ＋ do you get up?", near=["What time you get up?", "When time do you get up?"])
    q(71, "文法③", "まちがい直し", "次の対話の誤りを1か所直して、A の文を書こう。\nA: Where do you have in your bag?\nB: I have two books.", EN("What do you have in your bag?"), "「何を」持っているかを答えているので What。", near=["Where do you have in your bag?"])
    q(71, "文法③", "まちがい直し", "次の対話の誤りを1か所直して、A の文を書こう。\nA: When do you eat lunch?\nB: I eat in the classroom.", EN("Where do you eat lunch?"), "場所を答えているので Where。", near=["What do you eat lunch?"])
    q(71, "文法③", "まちがい直し", "次の対話の誤りを1か所直して、B の文を書こう。\nA: What time do you go to school?\nB: I go there in 7:30.", EN("I go there at 7:30."), "時刻の前は at。", near=["I go there on 7:30."])
    q(71, "文法③", "まちがい直し", "次の英文の誤りを1か所直して、全文を書こう。\nWho does run fast in your class?", EN("Who runs fast in your class?"), "Who が主語の文は〈Who ＋動詞（三単現）〉。does は使わない。", near=["Who run fast in your class?"])
