    q(68, "まとめテスト", "語を選ぶ", "次の（　）内から正しい語を選ぼう。\n(What / Why / Who) does he study English? — Because he wants to work abroad.", EN("Why"), "Because で答えているので Why。", near=["What", "Who"])
    q(68, "まとめテスト", "書きかえ", "下線部をたずねる文に書きかえよう（2語で始める）。\nThat is your book.（下線部：your）", EN("Whose book is that?"), "「だれの本」＝ Whose book。", near=["Who book is that?", "Whose is that book?"])
    q(68, "まとめテスト", "並べかえ", NARABE + "\nだれが私のかばんを使いましたか。（ used / who / bag / my ）?", EN("Who used my bag?"), "Who ＋ used（過去形）＋ my bag?", near=["Who my bag used?"])
