def l6b():
    u = unit('l6b', "代名詞（him・her・them など）と校舎案内", MAJ, {66, 67, 68, 69, 72, 73, 113},
             "2026-10-07 Claude作成。英語ワークp66〜67（Lesson6 Part3：目的格の代名詞 him・her など、必ず覚えたい語句、他者紹介）、p68〜69まとめテスト、p72 Useful Expressions①（校舎案内・フロアマップ）、p73文法④（代名詞の表とまちがい直し）、p113基本文総チェックを写真で確認し、人物・語・場面を変えて作り直した。手書きの答えは使っていない。")
    q = u.q
    table = [("I", "my", "me", "mine", "私"), ("you", "your", "you", "yours", "あなた"), ("he", "his", "him", "his", "彼"),
             ("she", "her", "her", "hers", "彼女"), ("we", "our", "us", "ours", "私たち"), ("they", "their", "them", "theirs", "彼ら")]
    for subj, pos, obj, own, ja in table:
        if subj != "you":
            q(73, "文法④", "代名詞の形", f"「{ja}を［に］」を表す代名詞を英語1語で書こう。", EN(obj), f"{subj}（{ja}は）→ {obj}（{ja}を・に）。", near=[x for x in (subj, pos, own) if x != obj])
        if subj not in ("I", "you", "he", "she"):
            q(73, "文法④", "代名詞の形", f"「{ja}の」を表す代名詞を英語1語で書こう。", EN(pos), f"{subj}（{ja}は）→ {pos}（{ja}の）。", near=[x for x in (subj, obj, own) if x != pos])
    q(73, "文法④", "代名詞の形", "「それの」を表す代名詞を英語1語で書こう（it's と区別）。", EN("its", fixed=True), "it（それは）→ its（それの）。it's は it is の短縮形。", near=["it's", "it"])
    q(66, "ポイント", "目的格", "代名詞が動詞や前置詞のあとにくるとき、どの形を使うか。次から選ぼう。\nア「～は」の形　イ「～の」の形　ウ「～を［に］」の形", T("ウ"), "動詞・前置詞のあとは「～を［に］」の形（him・her など）。", near=["ア", "イ"])
    q(66, "A", "目的格", "次の（　）内から正しい語を選ぼう。\nThis is Ken. Do you know (he / him)?", EN("him"), "know のあとなので him。", near=["he"])
    q(66, "A", "目的格", "次の（　）内から正しい語を選ぼう。\nEri has a dog. The dog likes (she / her) very much.", EN("her"), "likes のあとなので her。", near=["she"])
    q(66, "A", "目的格", "次の（　）内から正しい語を選ぼう。\nWho is that boy? — I don't know (he / him).", EN("him"), "know のあとなので him。", near=["he"])
    q(66, "A", "目的格", "（　）内の語を適する形にかえて書こう。\nThat's Jack. Do you know (he)?", EN("him"), "he → him。", near=["he", "his"])
    q(66, "A", "目的格", "（　）内の語を適する形にかえて書こう。\nWho is that girl? — I don't know (she).", EN("her"), "she → her。", near=["she", "hers"])
    q(66, "A", "目的格", "（　）内の語を適する形にかえて書こう。\nMy cats love (I).", EN("me"), "I → me。", near=["I", "my", "mine"])
    q(66, "A", "目的格", FILL + "\nこちらはエレンです。あなたは彼女を知っていますか。\nThis is Ellen. Do you know (　)?", EN("her"), "女性なので her。", near=["she", "him"])
    q(66, "A", "目的格", FILL + "\nこちらはルーカスです。あなたは彼を知っていますか。\n(　) is Lucas. Do you know (　)?（順に2語）", SEQ(["This", "him"], seps=(" ", "、", ",", ", ", "・")), "人を紹介するときは This is ～.。男性なので him。", near=["This he", "He him"])
    q(67, "B", "目的格", NARABE + "\n私は彼女が大好きです。（ like / her / I ）very much.", EN("I like her very much."), "I ＋ like ＋ her。", near=["I her like very much."])
    q(67, "B", "目的格", NARABE + "\n私たちに彼について教えてください。Please（ about / us / tell / him ）.", EN("Please tell us about him."), "tell ＋人（us）＋ about ～。", near=["Please tell about us him."])
